/* Question-bound vector manipulatives; diagrams use actual prompt values. */
(() => {
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const text=(x,y,s,size=20,fill='#193d49')=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="${size}" font-weight="650" fill="${fill}">${esc(s)}</text>`;
const line=(x,y,a,b,color='#178a8b',width=3)=>`<path d="M${x} ${y}L${a} ${b}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round"/>`;
const coin=(x,y,r=13)=>`<g class="coin-pop" style="--delay:${(x%7)*.04}s"><circle cx="${x}" cy="${y}" r="${r}" fill="url(#gold)" stroke="#bd7e22" stroke-width="2"/><circle cx="${x}" cy="${y}" r="${r*.71}" fill="none" stroke="#fff0a2" stroke-width="1.5"/><path d="M${x} ${y-r*.38}v${r*.76}" stroke="#b47b20" stroke-width="2"/></g>`;
const robot=(x,y,s=1,color='#31aeb0')=>`<g transform="translate(${x} ${y}) scale(${s})"><g class="bot-float"><ellipse cx="0" cy="98" rx="43" ry="7" fill="#1b55521a"/><path d="M0 -31v-16" stroke="#397d83" stroke-width="5"/><circle class="antenna" cy="-50" r="8" fill="#ffb64b"/><path d="M-29 42q-24 0-25 24m83-24q24 0 25 24" fill="none" stroke="${color}" stroke-width="13" stroke-linecap="round"/><rect x="-30" y="31" width="60" height="53" rx="19" fill="url(#ivory)" stroke="#518a8b" stroke-width="2"/><circle cy="56" r="12" fill="${color}"/><circle cy="56" r="5" fill="#bcefe4"/><rect x="-28" y="80" width="22" height="14" rx="6" fill="${color}"/><rect x="6" y="80" width="22" height="14" rx="6" fill="${color}"/><rect x="-55" y="-7" width="16" height="30" rx="8" fill="${color}"/><rect x="39" y="-7" width="16" height="30" rx="8" fill="${color}"/><rect x="-45" y="-33" width="90" height="68" rx="24" fill="url(#ivory)" stroke="#518a8b" stroke-width="2"/><path d="M-29-22h48" stroke="white" stroke-width="5" stroke-linecap="round" opacity=".8"/><rect x="-34" y="-22" width="68" height="44" rx="15" fill="url(#screen)"/><g class="bot-eyes"><path d="M-23-1q6-11 12 0m22 0q6-11 12 0" fill="none" stroke="#b8f5ef" stroke-width="3.5" stroke-linecap="round"/></g><path d="M-6 10q6 6 12 0" fill="none" stroke="#b8f5ef" stroke-width="3" stroke-linecap="round"/></g></g>`;
const card=(x,y,w,h)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="16" fill="#fffdf4" stroke="#b5d3c7" stroke-width="2"/>`;
const parts=(x,y,count,label,removed=false)=>{let body=card(x,y,220,140);const shown=Math.min(count,30),large=count<=10,cols=large?5:10,spacing=large?38:19,r=large?12:6;for(let j=0;j<shown;j++){const px=x+(large?34:24)+(j%cols)*spacing,py=y+(large?37:30)+Math.floor(j/cols)*(large?37:24);const empty=label==='empty slots';body+=`<g class="${removed?'part-out':'part-in'}" style="--delay:${j*.025}s"><rect x="${px-r}" y="${py-r}" width="${r*2}" height="${r*2}" rx="${large?5:3}" fill="${empty?'none':removed?'#e7a37d':'#31a7a6'}" stroke="#538e89" stroke-width="1.2" ${empty?'stroke-dasharray="3 2"':''}/><circle cx="${px}" cy="${py}" r="${r*.45}" fill="${empty?'none':'#d6f3e8'}" stroke="#73aaa0" stroke-width="1"/>${removed?line(px-r,py+r,px+r,py-r,'#913f2a',1.5):''}</g>`;}body+=text(x+110,y+121,`${count} ${count===1&&label==='parts'?'part':label}`,15);if(count>30)body+=text(x+110,y+96,`30 shown · +${count-30} in storage`,11);return body;};
function render(q,s,index){const t=s.topic,d=s.difficulty,g=s.grade,n=index+1,a=n+d+1,b=d+3;const nums=(q.text.match(/-?\d+(?:\.\d+)?/g)||[]).map(Number);let body='',caption='',kind=t;
const label=(str)=>text(390,44,str,16,'#397a76');
const equation=(left,op,right)=>card(170,90,200,130)+card(440,90,200,130)+text(270,164,left,30)+text(540,164,right,30)+text(405,166,op,30);
if(['add','subtract'].includes(t)){let x=nums[0],y=nums[1];body=parts(140,85,x,'parts')+parts(440,85,y,t==='subtract'?'used':'more',t==='subtract')+text(400,162,t==='subtract'?'−':'+',32);if(nums.length>2&&q.text.includes('7 more'))body+=text(390,260,'+ 7 spare parts arrive',18);if(q.text.includes('8 more'))body+=text(390,260,'Then use 8 more parts',18);if(q.text.includes('How many more')){body=parts(140,85,y,'parts ready')+parts(440,85,20-y,'empty slots')+text(390,263,'Fill the order of 20 parts',19);}caption='Count the parts. Crossed parts leave the workshop; new parts arrive.';}
else if(t==='patterns'||t==='sequence'){let first=t==='patterns'?n:a,step=d+(t==='patterns'?1:2);for(let j=0;j<4;j++){body+=card(150+j*130,100,110,90)+text(205+j*130,154,j===3&&t==='patterns'?'?':first+j*step,29);if(j<3)body+=text(270+j*130,93,`+${step}`,14);}if(t==='sequence')body+=text(390,250,g===11&&d===2?`Sum the first ${n+5} terms`:`Continue to term ${g===11?n+5:n+3}`,19);caption='The growing conveyor shows the first terms. Follow the same step each time.';}
else if(['groups','multiply','divide'].includes(t)){const divide=t==='divide'||t==='groups'&&index>=10;let count=divide?nums[1]:nums[0],each=divide?nums[0]/count:nums[1];for(let j=0;j<Math.min(count,8);j++){let x=152+(j%4)*143,y=85+Math.floor(j/4)*100;body+=card(x,y,126,83);for(let k=0;k<Math.min(each,10);k++)body+=coin(x+18+(k%5)*22,y+23+Math.floor(k/5)*22,7);body+=text(x+63,y+72,divide?'equal share':`${each} parts`,13);}body+=text(390,306,`${count} ${divide?'equal groups':'trays'}${count>8?' · 8 illustrated':''}${q.text.includes('spare')?` + ${nums[2]} spares`:''}${q.text.includes('uses 1')?' · use 1 from each':''}`,16);caption=divide?`Distribute ${nums[0]} batteries or parts among ${count} equal groups. Coins stand for parts.`:`Each tray represents ${each} parts. There are ${count} trays in the order.`;}
else if(['perimeter','area'].includes(t)){let w=nums[0],h=nums[1],ww=310,hh=155;body=`<rect x="240" y="85" width="${ww}" height="${hh}" rx="4" fill="url(#grid)" stroke="#158b8c" stroke-width="5" class="draw-outline"/>`+text(395,73,`${w} m`,21)+text(591,170,`${h} m`,21);if(d===2&&t==='area')body+='<rect x="240" y="85" width="64" height="45" fill="#efa478"/>'+text(272,113,'2 m²',13);body+=text(390,287,t==='perimeter'||d===0?'Trace all four sides':'Measure the floor inside',18);caption='Length and width match the question; the drawing is not to scale.';}
else if(t==='volume'){body='<path d="M250 115l100-65h230v145l-100 65H250z" fill="#d7ebe0" stroke="#20898c" stroke-width="3"/><path d="M250 115h230v145m0-145 100-65m-100 210 100-65" fill="none" stroke="#20898c" stroke-width="3"/>'+text(360,291,`${a} cm`,20)+text(610,130,`${b} cm`,20)+text(262,78,`${d+2} cm`,20);if(d===2)body+=text(390,325,'Two identical boxes',16);caption='A 3D storage box: multiply its three dimensions. Illustration not to scale.';}
else if(t==='fraction'||t==='percent'){let frac=t==='fraction',den=frac?d+2:100,num=frac?(d===2?3:1):[10,15,25][d],total=frac?a*den:a*10;let cells=frac?den:20;for(let j=0;j<cells;j++)body+=`<rect x="${185+(j%(frac?den:10))* (frac?400/den:42)}" y="${105+Math.floor(j/10)*48}" width="${frac?400/den-6:36}" height="${frac?95:40}" rx="5" fill="${j<cells*num/den?'#179fa0':'#dbe8dc'}" stroke="#9bbfb5"/>`;body+=text(390,250,`${total} ${frac?'parts':'coins'} in the whole`,22)+text(390,285,frac?`Take ${num} of ${den} equal shares`:`${num}% ${g===6?'of the whole':d===1?'increase':'discount'}`,18);caption=frac?'The bar is divided into equal shares. The shaded shares are the fraction requested.':'The bar models the percentage of the original price. Each small block represents 5%.';}
else if(t==='ratio'){for(let side=0;side<2;side++){let count=side?b+1:b;body+=card(170+side*235,82,210,165);for(let j=0;j<count;j++)body+=robot(202+side*235+(j%3)*63,120+Math.floor(j/3)*70,.32,side?'#368bc0':'#e78a62');body+=text(275+side*235,279,side?`${b+1} ratio parts blue`:`${b} ratio parts red`,16);}body+=text(390,312,`${b*a} red robots in the full order`,17);caption='One ratio group is shown. Scale both colours by the same amount.';}
else if(t==='probability'){let red=n+2,blue=n+4;if(d===2){body=equation('10 coins','×',`${Math.round(n/25*100)}%`)+text(390,270,'Payoff × probability → expected revenue',19);}else{body='<path d="M235 85q155-45 310 0l20 150q-170 75-350 0z" fill="#fffcf1" stroke="#8eb7a7" stroke-width="3"/>';for(let j=0;j<Math.min(red+blue,36);j++)body+=`<circle class="part-in" cx="${250+j%9*35}" cy="${115+Math.floor(j/9)*31}" r="11" fill="${j<red?'#e58962':'#41a7c1'}"/>`;body+=text(390,289,`${red} red + ${blue} blue${red+blue>36?' · sample shown':''}`,20);if(d===1)body+=text(390,320,'Draw → replace → draw again',16);}caption='Colours show the outcomes. The labels give the exact counts for the probability calculation.';}
else if(t==='pythagoras'||t==='trig'){body='<path d="M240 245V85L550 245Z" fill="#c9e6df" stroke="#178a8b" stroke-width="4" class="draw-outline"/><path d="M240 222h23v23" fill="none" stroke="#178a8b" stroke-width="2"/>';if(t==='pythagoras'){body+=text(390,278,d===1?'?':`${(d===2?5:3)*a}`,22)+text(210,160,`${(d===2?12:d===1?3:4)*a}`,22)+text(430,142,d===1?`${5*a}`:'?',25);}else{body+=text(425,146,`${a*3} cm`,22)+text(500,230,`${[30,45,60][d]}°`,17)+text(d===1?390:209,d===1?278:165,'?',28);}caption='The marked corner is 90°. Find the missing side using the given lengths or angle. Diagram not to scale.';}
else if(t==='integers'){const left=-a,right=b,result=d===0?left+right:d===1?left-right:left*right;const lo=Math.min(left,result,0)-2,hi=Math.max(0,right)+2,xx=v=>185+(v-lo)/(hi-lo)*430;body+=line(185,190,615,190);for(let j=0;j<=6;j++){let v=Math.round(lo+(hi-lo)*j/6);body+=line(xx(v),185,xx(v),195)+text(xx(v),217,v,13);}body+=coin(xx(left),150,15)+text(xx(left),120,`Start ${left}`,17);if(d<2)body+=`<path d="M${xx(left)} 165Q${(xx(left)+xx(result))/2} 80 ${xx(result)} 165" fill="none" stroke="#eb8b44" stroke-width="4" stroke-dasharray="8 5" class="flow"/>`+text(390,275,`${d===0?'Move right':'Move left'} ${b} steps`,20);else body+=text(390,275,`${b} groups of ${left}`,22);caption='Use the signed number line. The highlighted coin marks the starting value.';}
else if(t==='equation'){let c=n+3,k=d+2;body=line(390,110,390,240)+line(270,151,510,151)+line(390,130,300,203)+line(390,130,480,203)+'<path d="M225 202h150l-18 32H243zm180 0h150l-18 32H423z" fill="#b8ded5" stroke="#298c8c" stroke-width="2"/>'+text(300,185,d===2?`${k} × (x + ${c})`:`${k}x + ${c}`,23)+text(480,185,`${d===2?k*(a+c):k*a+c}`,25)+text(390,285,'Keep both sides balanced',19);caption='The balance represents the exact equation. Do the same operation to both sides.';}
else if(['slope','quadratic','derivative','exponential','logs'].includes(t)){let points=[],xmin=0,xmax=6,ymax=12,fn=x=>x,axisLabel='',marks='';if(t==='slope'){xmin=n-1;xmax=n+4;const y=n+2,m=d+2;fn=x=>d===2?m*x+y:m*(x-n)+y;ymax=Math.max(5,fn(xmax)+3);axisLabel=`Slope triangle: rise ${3*m} / run 3`;marks='';}if(t==='quadratic'){const r=a,sr=a+d+2;xmin=r-2;xmax=d===2?r+3:sr+2;fn=x=>d===2?(x-r)**2+sr:(x-r)*(x-sr);ymax=Math.max(10,sr+10);axisLabel=d===2?`Vertex form · x-centre ${r}`:'Find where the curve crosses y = 0';}if(t==='derivative'){xmax=3;fn=x=>a*x**(d+2)+(d===2?b*x:0);ymax=fn(3);axisLabel=`Slope of the tangent at x = ${d===0?1:2}`;}if(t==='exponential'){xmax=d+2;fn=x=>a*10*(1+[.1,.2,.25][d])**x;ymax=fn(xmax)*1.1;axisLabel=`Initial ${a*10} coins · growth ${[10,20,25][d]}% per year`;}if(t==='logs'){xmax=6;fn=x=>Math.log(Math.max(.06,x))/Math.log(d+2);ymax=3;axisLabel=d===0?`log₂(x) = ${n}`:d===1?`log₃(x) + ${n} = ${n+(index%5)+1}`:`log₄(x − ${n}) = ${(index%5)+1}`;}
const X=x=>215+(x-xmin)/(xmax-xmin)*360,Y=y=>255-y/ymax*175;body+=line(215,255,610,255,'#8baaa3',2)+line(215,290,215,65,'#8baaa3',2);for(let j=0;j<=4;j++){let x=xmin+(xmax-xmin)*j/4;body+=text(X(x),278,Math.round(x*10)/10,12);let y=ymax*j/4;body+=text(188,Y(y)+4,Math.round(y*10)/10,11)+line(215,Y(y),575,Y(y),'#d9e7df',1);}for(let j=0;j<=70;j++){let x=xmin+(xmax-xmin)*j/70;points.push(`${X(x)},${Y(fn(x))}`);}body+=`<polyline points="${points.join(' ')}" fill="none" stroke="#138e91" stroke-width="4" class="draw-curve"/>`+text(390,321,axisLabel,16);if(t==='derivative'){const x=d===0?1:2,grad=a*(d+2)*x**(d+1)+(d===2?b:0);body+=line(X(x-.6),Y(fn(x)-.6*grad),X(x+.6),Y(fn(x)+.6*grad),'#e58b48',3)+coin(X(x),Y(fn(x)),6);}if(t==='slope'){let y=d===2?(d+2)*n+n+2:n+2,m=d+2;body+=line(X(n),Y(y),X(n+3),Y(y),'#e58b48',3)+line(X(n+3),Y(y),X(n+3),Y(y+3*m),'#e58b48',3);}caption=t==='logs'?'The curve shows the logarithm family. Convert the given equation between logarithmic and exponential form.':'Follow the curve and its labelled axes. The graph models the relationship in your question.';}
else if(t==='decimal'){body=equation((a/10).toFixed(1),['+','×','÷'][d],(b/10).toFixed(1));for(let j=0;j<10;j++)body+=`<rect x="${190+j*40}" y="255" width="34" height="28" rx="4" fill="${j< a%10?'#e7ae43':'#d5e7df'}"/>`;body+=text(390,315,'Ten tenths make one whole coin',17);caption='The coin strip shows tenths of a whole, alongside the exact decimal operation.';}
else throw Error(`No artwork for ${t}`);
const svg=`<svg viewBox="0 0 780 350" role="img" aria-label="${esc(caption)}"><defs><linearGradient id="ivory" x2=".8" y2="1"><stop stop-color="#fffdf0"/><stop offset="1" stop-color="#b2d6d0"/></linearGradient><linearGradient id="screen" x2="1" y2="1"><stop stop-color="#245666"/><stop offset="1" stop-color="#102f40"/></linearGradient><radialGradient id="gold"><stop stop-color="#ffe595"/><stop offset="1" stop-color="#edb034"/></radialGradient><pattern id="grid" width="31" height="31" patternUnits="userSpaceOnUse"><rect width="31" height="31" fill="#d6e9df"/><path d="M31 0H0V31" fill="none" stroke="#b2d3c6"/></pattern><clipPath id="scene-clip"><rect x="0" y="0" width="780" height="350" rx="20"/></clipPath></defs><g clip-path="url(#scene-clip)"><rect width="780" height="350" rx="20" fill="#edf3e5"/><circle cx="720" cy="25" r="130" fill="#e4edda"/><path d="M0 330Q260 300 780 330v20H0" fill="#dce9d9"/>${robot(76,213,.8)}${body}</g></svg>`;
return `<figure class="question-art" data-visual="${kind}">${svg}<figcaption>${esc(caption)}</figcaption><button type="button" id="replay-art" aria-label="Replay diagram animation">↻ Replay visual</button></figure>`;
}
window.QuestionArt={render};
})();
